## Code Example
```javascript
interface Context { data: any; errors: string[] }

interface Step { name: string; run(ctx: Context): Promise<void> }
type StepFactory = () => Step

class Registry {
  private map = new Map<string, StepFactory>()
  register(name: string, factory: StepFactory) { this.map.set(name, factory) }
  resolve(name: string): Step { const f = this.map.get(name); if (!f) throw new Error(`Unknown step: ${name}`); return f() }
}

class Pipeline {
  constructor(private steps: string[], private registry: Registry) {}
  async run(ctx: Context) {
    for (const s of this.steps) {
      await this.registry.resolve(s).run(ctx)
    }
  }
}
```

